function hl(t){var H=[['<path d="M13 2L4 14h7l-1 8 9-12h-7z"/>',t('فاکتور در چند ثانیه','Invoices in seconds'),t('محصول و مشتری را انتخاب کن؛ فاکتور آماده است. کار چند دقیقه‌ای، چند ثانیه‌ای می‌شود.','Pick a product and a customer; the invoice is ready. Minutes of work become seconds.')],['<path d="M4 5h16M4 12h16M4 19h10"/>',t('فارسی‌اول','Persian-first'),t('تاریخ شمسی، تومان یا ریال و راست‌به‌چپ از ابتدا.','Jalali dates, Toman or Rial and RTL from day one.')],['<path d="M3 7l9-4 9 4v10l-9 4-9-4z"/>',t('انبار هوشمند','Stock-aware'),t('موجودی با هر فروش و خرید خودکار به‌روز می‌شود.','Stock updates automatically with every sale and purchase.')],['<path d="M4 20V10M10 20V4M16 20v-8M22 20H2"/>',t('نمودار ساده و پیشرفته','Simple & advanced charts'),t('سود، بدهکاران و پرفروش‌ها در یک نگاه.','Profit, debtors and top sellers at a glance.')],['<path d="M6 3h9l3 3v15H6z"/><path d="M9 11h6M9 15h6"/>',t('۱۰ طرح چاپ متفاوت','10 distinct print layouts'),t('هر طرح چیدمان خودش را دارد؛ رنگ را خودتان انتخاب کنید.','Each layout has its own structure; you pick the color.')],['<path d="M12 3l8 3v6c0 5-3.5 8-8 9-4.5-1-8-4-8-9V6z"/>',t('اطلاعات در اختیار شماست','Your data, your choice'),t('به‌طور پیش‌فرض روی دستگاه خودتان می‌ماند؛ فقط اگر وارد حساب CUDER شوید، همگام می‌شود.','It stays on your device by default; it syncs only if you sign in to a CUDER account.')]];return H.map(function(x){return'<div class="card"><div class="ico"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">'+x[0]+'</svg></div><h3>'+x[1]+'</h3><p>'+x[2]+'</p></div>'}).join('')}
